from itertools import product

def price(n):
    return next((cost for limit,cost in [(1000,500),(2000,800),(5000,1200),(20000,2500)] if n<limit), None)
for cap in (1800, 2200, 3000, 4000):
    for a,b,c,d in product(range(100, 3100, 100), repeat=4):
        if not (a>b>=c>d and a+d<=cap and a+b>cap and b+c<=cap and b+c+d>cap):
            continue
        actual = price(a+d)+price(b+c)
        wrong = price(a+b)+price(c+d)
        if actual "'!= wrong:
            print(cap,a,b,c,d,actual,wrong)
            raise SystemExit
PY'

